274	    label: "Boldteq on Facebook",
275	  },
276	];
277	
278	// ─── Main Footer export ───────────────────────────────────────────────────────
279	
280	export function Footer() {
281	  return (
282	    <footer className={styles['footer']}>
283	      <div className={styles['container-large-6']}>
284	        <div className={styles['column-x-large']}>
285	          {/* Two-column grid: newsletter | right side */}
286	          <div className={styles['footer-grid']}>
287	            {/* Left: newsletter */}
288	            <div className={styles['footer-main']}>
289	              <FooterNewsletter />
290	            </div>
291	
292	            {/* Right: logo + social + links */}
293	            <div className={styles['footer-right']}>
294	              {/* Logo + social row */}
295	              <div className={styles['footer-heading']}>
296	                <div className={styles['footer-column']}>
297	                  <Link href="/" aria-label="Open Boldteq Site" className={styles['footer-logo']}>
298	                    <Image
299	                      src="/images/webflow/f-new.svg"
300	                      alt="Boldteq logo"
301	                      width={120}
302	                      height={36}
303	                      style={{ height: "auto", width: "auto", objectFit: "contain" }}
304	                    />
305	                  </Link>
306	                </div>
307	
308	                {/* Social icons */}
309	                <div className={styles['row-regular']}>
310	                  {socialLinks.map(({ icon: Icon, href, label }) => (
311	                    <SocialLink key={label} href={href} label={label}>
312	                      <Icon />
313	                    </SocialLink>
314	                  ))}
315	                </div>
316	              </div>
317	
318	              {/* 4-column links grid */}
319	              <div className={styles['footer-links-grid']}>
320	                {Object.entries(footerLinks).map(([title, links]) => (
321	                  <FooterLinkColumn key={title} title={title} links={links} />
322	                ))}
323	              </div>
324	            </div>
325	          </div>
326	
327	          {/* Legal / copyright */}
328	          <div className={styles['footer-legal-wrapper']}>
329	            <div className={styles['copyright-outer']}>
330	              <p className={styles['copyright-text']}>
331	                Designed with ❤️ from India
332	              </p>
333	              <Image
334	                src="/images/webflow/🇮🇳.svg"
335	                alt="Indian National flag icon"
336	                width={18}
337	                height={18}
338	                className={styles['indian-flag']}
339	                onError={() => undefined}
340	              />
341	            </div>
342	          </div>
343	        </div>
344	      </div>
345	    </footer>
346	  );
347	}
